create or replace function public.barberium_create_appointment(p_barbershop_slug text,p_unit_slug text,p_professional_id uuid,p_service_id uuid,p_addon_service_ids uuid[],p_date date,p_time time,p_full_name text,p_phone text,p_birthday date default null,p_existing_token text default null) returns jsonb language plpgsql security definer set search_path='public','barberium','extensions' as $$
declare v_b public.barbershops; v_u public.units; v_s public.services; v_customer public.customers; v_phone text; v_duration int; v_base int; v_total int; v_start timestamptz; v_end timestamptz; v_appt public.appointments; v_plain_token text; v_issue_token boolean:=false;
begin if length(trim(coalesce(p_full_name,'')))<3 then raise exception 'INVALID_NAME'; end if; v_phone:=barberium.normalize_phone(p_phone); if v_phone is null then raise exception 'INVALID_PHONE'; end if; select * into v_b from public.barbershops where slug=p_barbershop_slug and status='active'; if not found then raise exception 'BARBERSHOP_NOT_FOUND'; end if; select * into v_u from public.units where barbershop_id=v_b.id and slug=p_unit_slug and is_active; if not found then raise exception 'UNIT_NOT_FOUND'; end if; select * into v_s from public.services where id=p_service_id and unit_id=v_u.id and is_active and service_kind in ('service','combo') and coalesce((settings->>'draft')::boolean,false)=false; if not found then raise exception 'SERVICE_NOT_FOUND'; end if; if not exists(select 1 from public.professionals where id=p_professional_id and unit_id=v_u.id and is_active) then raise exception 'PROFESSIONAL_NOT_FOUND'; end if; if not barberium.professional_service_allowed(p_professional_id,p_service_id) then raise exception 'PROFESSIONAL_NOT_LINKED'; end if; if exists(select 1 from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x where not exists(select 1 from public.service_addons a where a.base_service_id=p_service_id and a.addon_service_id=x and a.is_active) or not barberium.professional_service_allowed(p_professional_id,x)) then raise exception 'INVALID_ADDON'; end if; select * into v_customer from public.customers where barbershop_id=v_b.id and phone_e164=v_phone; if found then update public.customers set full_name=trim(p_full_name),birthday=coalesce(p_birthday,birthday) where id=v_customer.id returning * into v_customer; else insert into public.customers(barbershop_id,full_name,phone_e164,birthday) values(v_b.id,trim(p_full_name),v_phone,p_birthday) returning * into v_customer; v_issue_token:=true; end if; v_duration:=barberium.effective_service_duration(p_professional_id,p_service_id)+coalesce((select sum(barberium.effective_addon_duration(p_professional_id,p_service_id,x)) from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x),0); v_base:=barberium.effective_service_price(p_professional_id,p_service_id); v_total:=v_base+coalesce((select sum(barberium.effective_addon_price(p_professional_id,p_service_id,x)) from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x),0); v_start:=(p_date::timestamp+p_time) at time zone v_b.timezone; v_end:=v_start+make_interval(mins=>v_duration); if v_start<now() then raise exception 'PAST_SLOT'; end if; if not(to_char(p_time,'HH24:MI')=any(array(select jsonb_array_elements_text(public.barberium_get_available_slots(p_barbershop_slug,p_unit_slug,p_professional_id,p_service_id,coalesce(p_addon_service_ids,'{}'::uuid[]),p_date))))) then raise exception 'SLOT_UNAVAILABLE'; end if; begin insert into public.appointments(barbershop_id,unit_id,professional_id,customer_id,service_id,starts_at,ends_at,base_price_cents,total_price_cents,listed_price_cents,manual_adjustment_cents) values(v_b.id,v_u.id,p_professional_id,v_customer.id,p_service_id,v_start,v_end,v_base,v_total,v_total,0) returning * into v_appt; exception when exclusion_violation then raise exception 'SLOT_UNAVAILABLE'; end; insert into public.appointment_addons(appointment_id,service_id,name_snapshot,price_cents,duration_min) select v_appt.id,ad.id,ad.name,barberium.effective_addon_price(p_professional_id,p_service_id,ad.id),barberium.effective_addon_duration(p_professional_id,p_service_id,ad.id) from public.service_addons a join public.services ad on ad.id=a.addon_service_id where a.base_service_id=p_service_id and a.addon_service_id=any(coalesce(p_addon_service_ids,'{}'::uuid[])) and a.is_active; if v_issue_token then v_plain_token:=encode(extensions.gen_random_bytes(32),'hex'); insert into public.customer_access_tokens(customer_id,token_hash) values(v_customer.id,extensions.digest(v_plain_token,'sha256')); elsif p_existing_token is not null and barberium.valid_customer_token(v_customer.id,p_existing_token) then update public.customer_access_tokens set last_used_at=now() where customer_id=v_customer.id and token_hash=extensions.digest(p_existing_token,'sha256') and revoked_at is null; end if; select * into v_appt from public.appointments where id=v_appt.id; return jsonb_build_object('appointment_id',v_appt.id,'customer_id',v_customer.id,'access_token',v_plain_token,'starts_at',v_appt.starts_at,'ends_at',v_appt.ends_at,'total_price_cents',v_appt.total_price_cents); end $$;

create or replace function public.barberium_staff_create_appointment(p_customer_id uuid,p_full_name text,p_phone text,p_professional_id uuid,p_service_id uuid,p_addon_service_ids uuid[],p_date date,p_time time,p_final_price_cents integer default null,p_internal_note text default null) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$
declare m record; perms jsonb; v_prof public.professionals; v_service public.services; v_customer public.customers; v_b public.barbershops; v_phone text; v_duration int; v_base int; v_listed int; v_final int; v_start timestamptz; v_end timestamptz; v_appt public.appointments;
begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Usuário sem acesso à equipe'; end if; perms:=case when m.role in ('owner','admin') then barberium.default_barber_permissions() else barberium.effective_permissions(m.professional_id) end; if m.role not in ('owner','admin') and not barberium.permission_enabled(perms,'create_appointment') then raise exception 'Sem permissão para criar agendamentos'; end if; if m.role='barber' then p_professional_id:=m.professional_id; end if; select * into v_prof from public.professionals where id=p_professional_id and barbershop_id=m.barbershop_id and is_active; if not found then raise exception 'Profissional inválido'; end if; select * into v_service from public.services where id=p_service_id and unit_id=v_prof.unit_id and is_active; if not found then raise exception 'Serviço inválido'; end if; if not barberium.professional_service_allowed(v_prof.id,v_service.id) then raise exception 'Profissional não vinculado ao serviço'; end if; if exists(select 1 from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x where not exists(select 1 from public.service_addons a where a.base_service_id=p_service_id and a.addon_service_id=x and a.is_active) or not barberium.professional_service_allowed(v_prof.id,x)) then raise exception 'Adicional inválido para este profissional'; end if; if p_customer_id is not null then select * into v_customer from public.customers where id=p_customer_id and barbershop_id=m.barbershop_id; if not found then raise exception 'Cliente inválido'; end if; else if length(trim(coalesce(p_full_name,'')))<3 then raise exception 'Informe o nome do cliente'; end if; v_phone:=barberium.normalize_phone(p_phone); if v_phone is null then raise exception 'Informe um WhatsApp válido'; end if; select * into v_customer from public.customers where barbershop_id=m.barbershop_id and phone_e164=v_phone; if found then update public.customers set full_name=trim(p_full_name),updated_at=now() where id=v_customer.id returning * into v_customer; else insert into public.customers(barbershop_id,full_name,phone_e164) values(m.barbershop_id,trim(p_full_name),v_phone) returning * into v_customer; end if; end if; if p_internal_note is not null and trim(p_internal_note)<>'' and m.role not in ('owner','admin') and not barberium.permission_enabled(perms,'edit_internal_note') then raise exception 'Sem permissão para observação interna'; end if; select * into v_b from public.barbershops where id=m.barbershop_id; v_duration:=barberium.effective_service_duration(v_prof.id,v_service.id)+coalesce((select sum(barberium.effective_addon_duration(v_prof.id,v_service.id,x)) from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x),0); v_base:=barberium.effective_service_price(v_prof.id,v_service.id); v_listed:=v_base+coalesce((select sum(barberium.effective_addon_price(v_prof.id,v_service.id,x)) from unnest(coalesce(p_addon_service_ids,'{}'::uuid[])) x),0); v_final:=coalesce(p_final_price_cents,v_listed); if v_final<0 then raise exception 'Valor inválido'; end if; if v_final<>v_listed and m.role not in ('owner','admin') and not barberium.permission_enabled(perms,'edit_value') then raise exception 'Sem permissão para alterar valor'; end if; v_start:=(p_date::timestamp+p_time) at time zone coalesce(v_b.timezone,'America/Sao_Paulo'); v_end:=v_start+make_interval(mins=>v_duration); if v_start<now() then raise exception 'Não é possível criar horário no passado'; end if; if exists(select 1 from public.appointments a where a.professional_id=v_prof.id and a.status='confirmed' and tstzrange(a.starts_at,a.ends_at,'[)')&&tstzrange(v_start,v_end,'[)')) then raise exception 'Horário ocupado'; end if; if barberium.has_block_conflict(v_prof.unit_id,v_prof.id,v_start,v_end,null,null) then raise exception 'Horário bloqueado'; end if; begin insert into public.appointments(barbershop_id,unit_id,professional_id,customer_id,service_id,starts_at,ends_at,base_price_cents,total_price_cents,listed_price_cents,manual_adjustment_cents,internal_note,created_by_member_id) values(m.barbershop_id,v_prof.unit_id,v_prof.id,v_customer.id,v_service.id,v_start,v_end,v_base,v_final,v_listed,v_final-v_listed,nullif(trim(coalesce(p_internal_note,'')),''),m.member_id) returning * into v_appt; exception when exclusion_violation then raise exception 'Horário ocupado'; end; insert into public.appointment_addons(appointment_id,service_id,name_snapshot,price_cents,duration_min) select v_appt.id,ad.id,ad.name,barberium.effective_addon_price(v_prof.id,v_service.id,ad.id),barberium.effective_addon_duration(v_prof.id,v_service.id,ad.id) from public.service_addons a join public.services ad on ad.id=a.addon_service_id where a.base_service_id=v_service.id and a.addon_service_id=any(coalesce(p_addon_service_ids,'{}'::uuid[])) and a.is_active; insert into public.appointment_events(barbershop_id,appointment_id,actor_member_id,event_type,details) values(m.barbershop_id,v_appt.id,m.member_id,'created',jsonb_build_object('professional',v_prof.name,'service',v_service.name,'starts_at',v_start,'total_price_cents',v_final)); return jsonb_build_object('ok',true,'appointment_id',v_appt.id); end $$;

